export function ProfileDock({name,id,onProfile,communities=[]}:{name:string;id:string;onProfile:()=>void;communities?:{id:string;name:string}[]}){const v=useVoice(),central=useSettings();const started=useRef({session:'',at:0});const [seconds,setSeconds]=useState(0);const session=v.view?.joined?v.view.session:'';
 useEffect(()=>{if(!session){started.current={session:'',at:0};setSeconds(0);return};if(started.current.session!==session)started.current={session,at:performance.now()};return visualPolling(()=>setSeconds(Math.floor((performance.now()-started.current.at)/1000)),1000)},[session]);
 return <section className={'profile-dock '+(v.view?.joined?'in-call':'')+(v.stageContainer?' in-room':'')} aria-label="Perfil e controles de áudio">{v.view?.joined&&<CallPanel condensed={!!v.stageContainer} channel={v.view.channelName||v.label||'Canal de voz'} community={v.view.communityName||communities.find(c=>c.id===v.view?.community)?.name||'Comunidade'} participants={v.view.participants.length} seconds={seconds} mediaState={v.view.media.state} bridgePackets={v.view.bridgePackets} packetsOut={v.view.media.packetsOut} packetsIn={v.view.media.packetsIn} muted={v.view.muted} deaf={v.view.deaf} sharing={v.screen.sharing} screenReady={v.screen.ready} screenBusy={v.screen.busy} onMute={()=>void v.control(!v.view?.muted,!!v.view?.deaf)} onDeaf={()=>void v.control(!!v.view?.muted,!v.view?.deaf)} onScreen={v.screenAction} onLeave={()=>void v.leave()} onDiagnostics={v.openDiagnostics}/>}
 <div className="profile-row"><button className="profile-identity" onClick={onProfile} title="Abrir perfil"><IdentityAvatar className="avatar own" id={id} name={name}/><span><b><IdentityName id={id} name={name}/></b><small>{v.view?.joined?'Em chamada · '+callDuration(seconds):'Seu perfil local'}</small></span></button>{!v.view?.joined&&<><button className="icon" title="Microfone disponível ao entrar em uma sala" aria-label="Microfone desconectado" disabled><Mic size={17}/></button><button className="icon" title="Áudio disponível ao entrar em uma sala" aria-label="Áudio desconectado" disabled><Headphones size={17}/></button></>}<button className="icon principal-settings" data-settings-entry="true" title="Configurações" aria-label="Configurações" onClick={()=>central.open()}><Settings size={17}/></button><span className="sr-only">{id}</span></div></section>}
